#include "McpTool.hpp"

#include <regex>
#include <stdexcept>

#include "McpSchema.hpp"

namespace Slic3r { namespace GUI { namespace Mcp {

// McpToolGroups.inc is generated by src/slic3r/Mcp/CMakeLists.txt: one MCP_GROUP(<Group>) line for
// every tools/Tools<Group>.cpp, sorted by name.
#define MCP_GROUP(Group) void register_tools_##Group(ToolRegistry& registry);
#include "McpToolGroups.inc"
#undef MCP_GROUP

json to_json(const DialogRecord& record)
{
    json out = json::object();
    out["title"] = record.title;
    out["message"] = record.message;
    out["answered"] = record.answered;
    return out;
}

void ToolRegistry::add(ToolDef def)
{
    static const std::regex name_re("^[a-z][a-z0-9_]{0,63}$");
    if (!std::regex_match(def.name, name_re))
        throw std::logic_error("MCP tool name \"" + def.name + "\" is not snake_case");
    if (def.debug_only && !m_with_debug_tools)
        return;
    if (m_index.count(def.name) != 0)
        throw std::logic_error("MCP tool \"" + def.name + "\" is registered twice (second time by group " + m_current_group + ")");
    if (!def.handler)
        throw std::logic_error("MCP tool \"" + def.name + "\" has no handler");
    if (def.description.empty() || def.description.size() > 4000)
        throw std::logic_error("MCP tool \"" + def.name + "\": the description must have 1 to 4000 characters");

    if (def.input_schema.is_null())
        def.input_schema = json::object({{"type", "object"}, {"properties", json::object()}, {"additionalProperties", false}});
    if (!def.input_schema.is_object() || def.input_schema.value("type", std::string()) != "object")
        throw std::logic_error("MCP tool \"" + def.name + "\": input_schema must be an object schema");
    if (!def.input_schema.contains("properties"))
        def.input_schema["properties"] = json::object();
    if (!def.read_only && def.accepts_if_rev && !def.input_schema["properties"].contains("if_rev"))
        def.input_schema["properties"]["if_rev"] = json::object(
            {{"type", "integer"}, {"description", "Fail with `conflict` unless the scene revision (rev from scene_get or the last result) still has this value."}});
    def.input_schema = Schema::with_shared_defs(std::move(def.input_schema));
    if (const std::string problem = Schema::check_schema(def.input_schema); !problem.empty())
        throw std::logic_error("MCP tool \"" + def.name + "\": bad input_schema: " + problem);

    if (def.title.empty())
        def.title = def.name;
    if (def.queue_timeout_ms <= 0)
        def.queue_timeout_ms = def.read_only ? 15000 : 30000;
    if (def.run_timeout_ms <= 0)
        def.run_timeout_ms = 120000;

    m_groups[def.name] = m_current_group;
    m_index[def.name] = m_tools.size();
    m_tools.push_back(std::move(def));
}

const ToolDef* ToolRegistry::find(const std::string& name) const
{
    auto it = m_index.find(name);
    return it == m_index.end() ? nullptr : &m_tools[it->second];
}

const std::string& ToolRegistry::group_of(const std::string& tool_name) const
{
    static const std::string none;
    auto it = m_groups.find(tool_name);
    return it == m_groups.end() ? none : it->second;
}

void ToolRegistry::finalize()
{
    m_list = json::array();
    for (const ToolDef& def : m_tools) {
        json annotations = json::object();
        annotations["title"] = def.title;
        annotations["readOnlyHint"] = def.read_only;
        annotations["destructiveHint"] = def.destructive;
        annotations["idempotentHint"] = def.idempotent;
        // Nothing here reaches beyond this machine.
        annotations["openWorldHint"] = false;

        json tool = json::object();
        tool["name"] = def.name;
        tool["title"] = def.title;
        tool["description"] = def.description;
        tool["inputSchema"] = def.input_schema;
        tool["annotations"] = std::move(annotations);
        m_list.push_back(std::move(tool));
    }
}

std::unique_ptr<ToolRegistry> ToolRegistry::create(bool with_debug_tools)
{
    auto registry = std::make_unique<ToolRegistry>();
    registry->m_with_debug_tools = with_debug_tools;
#define MCP_GROUP(Group)                 \
    registry->m_current_group = #Group;  \
    register_tools_##Group(*registry);
#include "McpToolGroups.inc"
#undef MCP_GROUP
    registry->m_current_group.clear();
    registry->finalize();
    return registry;
}

}}} // namespace Slic3r::GUI::Mcp
